import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static void bitAdd(long[] t, int i, long x) {
        int n = t.length - 1;
        for (; i <= n; i += i & -i) t[i] += x;
    }

    static long bitSum(long[] t, int i) {
        long s = 0;
        for (; i > 0; i -= i & -i) s += t[i];
        return s;
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long k = Long.parseLong(next());

        int cn = (int) n;
        long[] t = new long[cn + 1];
        for (int i = 1; i <= cn; i++) bitAdd(t, i, 1);
        int top = 1;
        while (top * 2 <= cn) top *= 2;
        long pos = 0;
        for (int m = cn; m > 1; m--) {
            long idx = (pos + k - 1) % m;
            long j = idx + 1;
            int p = 0;
            for (int step = top; step > 0; step >>= 1) {
                if (p + step <= cn && t[p + step] < j) {
                    p += step;
                    j -= t[p];
                }
            }
            bitAdd(t, p + 1, -1);
            pos = idx;
        }
        long j = 1;
        int p = 0;
        for (int step = top; step > 0; step >>= 1) {
            if (p + step <= cn && t[p + step] < j) {
                p += step;
                j -= t[p];
            }
        }
        System.out.println(p + 1);
    }
}
